public async Task<Resultado<DocumentoDto>> ObterAsync(string documentoId)
{
    var documento = await _documentos
        .Find(d => d.Id == documentoId)
        .FirstOrDefaultAsync();

    if (documento == null)
        return Resultado<DocumentoDto>.Falha("Documento não encontrado");

    return Resultado<DocumentoDto>.Ok(MapearParaDto(documento));
}

