export class NotificacoesComponent implements OnInit {
  notificacoes: Notificacao[] = [];

  constructor(private chatService: ChatService) {}

  ngOnInit() {
    // notificacoes$ é Subject do hub do chat: não termina sozinho
    this.chatService.notificacoes$
      .subscribe(lista => this.notificacoes = lista);
  }
}

